export function shownName(route){return typeof route==="string"?route.replace(/\.[0-9a-f]{8}$/,""):route}export async function deploymentNamed(sb,name,columns){const got=await sb.from("deployments").select(columns).eq("name",name).limit(1);if(got.error||got.data&&got.data.length||name.includes("."))return got;const marked=await sb.from("deployments").select(columns).like("name",`${name}.%`).limit(20);if(marked.error)return marked;return{data:(marked.data||[]).filter((d=>shownName(d.name)===name)).slice(0,1),error:null}}